function withIdempotency(handler) {
  return async (req) => {
    const key = req.headers['idempotency-key']
    if (!key) return handler(req)
    const seen = await store.get(key)
    if (seen && seen.bodyHash !== hash(req.body)) return status(422)
    if (seen && seen.state === 'running') return status(409)
    if (seen) return seen.response
    await store.claim(key, hash(req.body))
    const response = await handler(req)
    await store.save(key, response)
    return response
  }
}
